`timescale 1ns / 1ps
`default_nettype none

// Xilinx clock generation (SPEC 7.6, ADR-015, ADR-023).  Only used under Vivado.
//   MMCM1 (MMCME2_BASE) makes clk_safe from the 20 MHz board clock on pin B13.
//   MMCM2 sits inside a Clocking Wizard v6.0 (clk_wiz_turbo, generated by fpga/synth_official.tcl)
//   with AXI4-Lite dynamic reconfiguration; clkwiz_seq programs it per turbo level (PG065).
//   A BUFGCTRL muxes clk_safe and clk_turbo into clk_fast.
// DS189 Table 37 limits (VCO 600-1200 MHz for -1) are respected by the level table in
// rtl/gen/mmcm_turbo_table.vh.  The safe divider can be set at synthesis time with
// -verilog_define SENTINEL_SAFE_DIV=10.0 (100 MHz) when 125 MHz does not meet timing.
`ifndef SENTINEL_SAFE_DIV
`define SENTINEL_SAFE_DIV 8.0
`endif

module clk_gen_xilinx #(
    parameter LEVELS_LOG2 = 4,
    parameter real CLKIN_PERIOD = 50.0,                 // 20 MHz
    parameter real SAFE_MULT    = 50.0,                 // VCO 1000 MHz
    parameter real SAFE_DIV     = `SENTINEL_SAFE_DIV,   // clk_safe = 1000 / SAFE_DIV MHz
    parameter      MUX_SETTLE   = 15                    // clk_safe cycles before the new mux state is reported
) (
    input  wire                   clk_in,
    input  wire                   rst,
    output wire                   clk_safe,
    output wire                   clk_fast,
    output wire                   locked,
    input  wire                   sel_turbo,
    output reg                    is_turbo,
    input  wire                   reconfig_start,
    input  wire [LEVELS_LOG2-1:0] reconfig_level,
    output wire                   reconfig_busy,
    output wire                   turbo_locked
);
    wire clk_safe_raw, safe_fb, safe_fb_buf, locked1, locked2, clk_safe_buf, clk_turbo_buf;

    // ---- MMCM1: the safe clock ----------------------------------------------------------------
    MMCME2_BASE #(
        .CLKIN1_PERIOD(CLKIN_PERIOD), .CLKFBOUT_MULT_F(SAFE_MULT), .CLKOUT0_DIVIDE_F(SAFE_DIV), .DIVCLK_DIVIDE(1)
    ) u_mmcm1 (
        .CLKIN1(clk_in), .CLKFBIN(safe_fb_buf), .RST(rst), .PWRDWN(1'b0),
        .CLKFBOUT(safe_fb), .CLKFBOUTB(), .CLKOUT0(clk_safe_raw), .CLKOUT0B(), .CLKOUT1(), .CLKOUT1B(),
        .CLKOUT2(), .CLKOUT2B(), .CLKOUT3(), .CLKOUT3B(), .CLKOUT4(), .CLKOUT5(), .CLKOUT6(), .LOCKED(locked1));

    BUFG u_fb1 (.I(safe_fb), .O(safe_fb_buf));
    BUFG u_safe (.I(clk_safe_raw), .O(clk_safe_buf));

    // ---- AXI reset for the wizard (ADR-021) -------------------------------------------------
    // MMCM1 is held in reset by rst, so its LOCKED is low during the power-on reset: synchronising
    // LOCKED alone covers both.  A second synchronizer on rst would fan the power-on reset flop out
    // to two synchronizers in clk_safe (report_cdc CDC-11).
    (* ASYNC_REG = "TRUE" *) reg [1:0] axi_lock_meta;
    reg axi_rst;
    initial begin
        axi_lock_meta = 2'b00;
        axi_rst       = 1'b1;
    end
    always @(posedge clk_safe_buf) begin
        axi_lock_meta <= {axi_lock_meta[0], locked1};
        axi_rst       <= ~axi_lock_meta[1];
    end

    // ---- MMCM2 inside the Clocking Wizard, reconfigured over AXI4-Lite -----------------------
    wire [10:0] awaddr, araddr;
    wire [31:0] wdata, rdata;
    wire [3:0]  wstrb;
    wire [1:0]  bresp, rresp;
    wire        awvalid, awready, wvalid, wready, bvalid, bready, arvalid, arready, rvalid, rready;

    clk_wiz_turbo u_turbo (
        .s_axi_aclk(clk_safe_buf), .s_axi_aresetn(~axi_rst),
        .s_axi_awaddr(awaddr), .s_axi_awvalid(awvalid), .s_axi_awready(awready),
        .s_axi_wdata(wdata), .s_axi_wstrb(wstrb), .s_axi_wvalid(wvalid), .s_axi_wready(wready),
        .s_axi_bresp(bresp), .s_axi_bvalid(bvalid), .s_axi_bready(bready),
        .s_axi_araddr(araddr), .s_axi_arvalid(arvalid), .s_axi_arready(arready),
        .s_axi_rdata(rdata), .s_axi_rresp(rresp), .s_axi_rvalid(rvalid), .s_axi_rready(rready),
        .clk_out1(clk_turbo_buf), .locked(locked2), .clk_in1(clk_in));

    // LOCKED of MMCM2 is asynchronous to clk_safe (ADR-021).
    (* ASYNC_REG = "TRUE" *) reg [1:0] locked2_meta;
    initial locked2_meta = 2'b00;
    always @(posedge clk_safe_buf) locked2_meta <= {locked2_meta[0], locked2};

    clkwiz_seq u_seq (
        .clk(clk_safe_buf), .rst(axi_rst), .start(reconfig_start), .level(reconfig_level), .busy(reconfig_busy),
        .locked(locked2_meta[1]),
        .m_awaddr(awaddr), .m_awvalid(awvalid), .m_awready(awready), .m_wdata(wdata), .m_wstrb(wstrb),
        .m_wvalid(wvalid), .m_wready(wready), .m_bvalid(bvalid), .m_bready(bready),
        .m_araddr(araddr), .m_arvalid(arvalid), .m_arready(arready), .m_rdata(rdata), .m_rvalid(rvalid), .m_rready(rready));

    wire unused_resp = &{1'b0, bresp, rresp};

    // ---- clk_fast: glitch-free mux of the two clocks ------------------------------------------
    BUFGCTRL #(.INIT_OUT(0), .PRESELECT_I0("TRUE"), .PRESELECT_I1("FALSE")) u_mux (
        .I0(clk_safe_buf), .I1(clk_turbo_buf), .S0(~sel_turbo), .S1(sel_turbo),
        .CE0(1'b1), .CE1(1'b1), .IGNORE0(1'b0), .IGNORE1(1'b0), .O(clk_fast));

    // The BUFGCTRL has no status output, so the new state is reported MUX_SETTLE clk_safe cycles
    // after the select last changed (SPEC 7.7).  The switch-over itself waits for edges of both
    // input clocks; the settle time is chosen to cover that, not taken from UG472 (not read).
    reg [4:0] settle;
    reg       sel_q;
    initial begin
        settle   = 5'd0;
        sel_q    = 1'b0;
        is_turbo = 1'b0;
    end
    always @(posedge clk_safe_buf) begin
        sel_q <= sel_turbo;
        if (sel_turbo != sel_q) settle <= 5'd0;
        else if (settle != MUX_SETTLE[4:0]) settle <= settle + 1'b1;
        else is_turbo <= sel_q;
    end

    assign clk_safe     = clk_safe_buf;
    assign locked       = locked1;
    assign turbo_locked = locked2_meta[1];
endmodule

`default_nettype wire
